//alt:float32 func SwiGLUFloat32SIMD(in, out []float32, numRows, hiddenDim int) {
func SwiGLUFloat64SIMD(in, out []float64, numRows, hiddenDim int) { //alt:float64
	//alt:float32 vLen := simd.BroadcastFloat32s(0).Len()
	vLen := simd.BroadcastFloat64s(0).Len() //alt:float64
	for m := range numRows {
		inOffset := m * 2 * hiddenDim
		outOffset := m * hiddenDim
		j := 0
		for ; j+vLen <= hiddenDim; j += vLen {
			//alt:float32 vGate := simd.LoadFloat32s(in[inOffset+j:])
			vGate := simd.LoadFloat64s(in[inOffset+j:]) //alt:float64
			//alt:float32 vVal := simd.LoadFloat32s(in[inOffset+hiddenDim+j:])
			vVal := simd.LoadFloat64s(in[inOffset+hiddenDim+j:]) //alt:float64
			//alt:float32 siluGate := vGate.Mul(simdmath.SigmoidFloat32(vGate))
			siluGate := vGate.Mul(simdmath.SigmoidFloat64(vGate)) //alt:float64
			siluGate.Mul(vVal).Store(out[outOffset+j:])
		}
		if j < hiddenDim {
			//alt:float32 vGate, _ := simdmath.LoadFloat32sPart(in[inOffset+j:])
			vGate, _ := simdmath.LoadFloat64sPart(in[inOffset+j:]) //alt:float64
			//alt:float32 vVal, _ := simdmath.LoadFloat32sPart(in[inOffset+hiddenDim+j:])
			vVal, _ := simdmath.LoadFloat64sPart(in[inOffset+hiddenDim+j:]) //alt:float64
			//alt:float32 siluGate := vGate.Mul(simdmath.SigmoidFloat32(vGate))
			siluGate := vGate.Mul(simdmath.SigmoidFloat64(vGate)) //alt:float64
			siluGate.Mul(vVal).StorePart(out[outOffset+j:])
		}
	}
}

