//alt:float32 func vjpGeluApproxFloat32SIMD(y, x, dOutput, dx []float32) {
func vjpGeluApproxFloat64SIMD(y, x, dOutput, dx []float64) { //alt:float64
	//alt:float32 vHalf := simd.BroadcastFloat32s(0.5)
	vHalf := simd.BroadcastFloat64s(0.5) //alt:float64
	//alt:float32 vOne := simd.BroadcastFloat32s(1.0)
	vOne := simd.BroadcastFloat64s(1.0) //alt:float64
	//alt:float32 vSqrt2ByPi := simd.BroadcastFloat32s(0.7978845608)
	vSqrt2ByPi := simd.BroadcastFloat64s(0.7978845608) //alt:float64
	//alt:float32 vConst044715 := simd.BroadcastFloat32s(0.044715)
	vConst044715 := simd.BroadcastFloat64s(0.044715) //alt:float64
	//alt:float32 vConst0134145 := simd.BroadcastFloat32s(0.134145)
	vConst0134145 := simd.BroadcastFloat64s(0.134145) //alt:float64
	vLen := vHalf.Len()
	i := 0
	for ; i+vLen <= len(dOutput); i += vLen {
		//alt:float32 vX := simd.LoadFloat32s(x[i:])
		vX := simd.LoadFloat64s(x[i:]) //alt:float64
		//alt:float32 vDOut := simd.LoadFloat32s(dOutput[i:])
		vDOut := simd.LoadFloat64s(dOutput[i:]) //alt:float64
		x2 := vX.Mul(vX)
		x3 := x2.Mul(vX)
		u := vSqrt2ByPi.Mul(vX.MulAdd(vConst044715, x3))
		uPrime := vSqrt2ByPi.Mul(x2.MulAdd(vConst0134145, vOne))
		//alt:float32 t := simdmath.TanhFloat32(u)
		t := simdmath.TanhFloat64(u) //alt:float64
		fPrime := vHalf.Mul(vOne.Add(t)).Add(vHalf.Mul(vX).Mul(vOne.Sub(t.Mul(t))).Mul(uPrime))
		vDOut.Mul(fPrime).Store(dx[i:])
	}
	if i < len(dOutput) {
		//alt:float32 vX, _ := simdmath.LoadFloat32sPart(x[i:])
		vX, _ := simdmath.LoadFloat64sPart(x[i:]) //alt:float64
		//alt:float32 vDOut, _ := simdmath.LoadFloat32sPart(dOutput[i:])
		vDOut, _ := simdmath.LoadFloat64sPart(dOutput[i:]) //alt:float64
		x2 := vX.Mul(vX)
		x3 := x2.Mul(vX)
		u := vSqrt2ByPi.Mul(vX.MulAdd(vConst044715, x3))
		uPrime := vSqrt2ByPi.Mul(x2.MulAdd(vConst0134145, vOne))
		//alt:float32 t := simdmath.TanhFloat32(u)
		t := simdmath.TanhFloat64(u) //alt:float64
		fPrime := vHalf.Mul(vOne.Add(t)).Add(vHalf.Mul(vX).Mul(vOne.Sub(t.Mul(t))).Mul(uPrime))
		vDOut.Mul(fPrime).StorePart(dx[i:])
	}
}

//alt:float32 func vjpSwiGLUFloat32SIMD(x, dOutput, dx []float32, numRows, hiddenDim int) {
func vjpSwiGLUFloat64SIMD(x, dOutput, dx []float64, numRows, hiddenDim int) { //alt:float64
	//alt:float32 vOne := simd.BroadcastFloat32s(1)
	vOne := simd.BroadcastFloat64s(1) //alt:float64
	vLen := vOne.Len()
	for m := range numRows {
		xOffset := m * 2 * hiddenDim
		dOutOffset := m * hiddenDim
		j := 0
		for ; j+vLen <= hiddenDim; j += vLen {
			//alt:float32 vGate := simd.LoadFloat32s(x[xOffset+j:])
			vGate := simd.LoadFloat64s(x[xOffset+j:]) //alt:float64
			//alt:float32 vVal := simd.LoadFloat32s(x[xOffset+hiddenDim+j:])
			vVal := simd.LoadFloat64s(x[xOffset+hiddenDim+j:]) //alt:float64
			//alt:float32 vDOut := simd.LoadFloat32s(dOutput[dOutOffset+j:])
			vDOut := simd.LoadFloat64s(dOutput[dOutOffset+j:]) //alt:float64

			//alt:float32 s := simdmath.SigmoidFloat32(vGate)
			s := simdmath.SigmoidFloat64(vGate) //alt:float64
			swish := vGate.Mul(s)
			swishPrime := s.Mul(vOne.Add(vGate.Mul(vOne.Sub(s))))

			vDOut.Mul(vVal).Mul(swishPrime).Store(dx[xOffset+j:])
			vDOut.Mul(swish).Store(dx[xOffset+hiddenDim+j:])
		}
		if j < hiddenDim {
			//alt:float32 vGate, _ := simdmath.LoadFloat32sPart(x[xOffset+j:])
			vGate, _ := simdmath.LoadFloat64sPart(x[xOffset+j:]) //alt:float64
			//alt:float32 vVal, _ := simdmath.LoadFloat32sPart(x[xOffset+hiddenDim+j:])
			vVal, _ := simdmath.LoadFloat64sPart(x[xOffset+hiddenDim+j:]) //alt:float64
			//alt:float32 vDOut, _ := simdmath.LoadFloat32sPart(dOutput[dOutOffset+j:])
			vDOut, _ := simdmath.LoadFloat64sPart(dOutput[dOutOffset+j:]) //alt:float64

			//alt:float32 s := simdmath.SigmoidFloat32(vGate)
			s := simdmath.SigmoidFloat64(vGate) //alt:float64
			swish := vGate.Mul(s)
			swishPrime := s.Mul(vOne.Add(vGate.Mul(vOne.Sub(s))))

			vDOut.Mul(vVal).Mul(swishPrime).StorePart(dx[xOffset+j:])
			vDOut.Mul(swish).StorePart(dx[xOffset+hiddenDim+j:])
		}
	}
}
